      map_season1_map1_name: "Grassland Village", map_season1_map1_tagline: "The village of beginnings, spread across peaceful lowlands", map_season1_map1_photo_1: "Main (aerial view)", map_season1_map1_photo_2: "View from the north", map_season1_map1_photo_3: "View from the south", map_season1_map1_photo_4: "View from the west", map_season1_map1_photo_5: "View from the east", map_season1_map1_photo_6: "View inside the cave", map_season1_map1_feature_1: "A central river crossed by several bridges connecting the village", map_season1_map1_feature_2: "Watchtowers to the north and south overlook the surroundings", map_season1_map1_feature_3: "A hidden item lies deep in the cave", map_season1_map1_feature_4: "Open terrain that's easy to move around in — a great first map", map_season1_map1_history: "Said to be the village where adventurers first gathered, earlier than anywhere else on the continent. Surrounded by rivers and hills, this land is the starting point of every story yet to come.",
      map_season1_map2_name: "Forgotten Canyon", map_season1_map2_tagline: "Cross the scars left by an ancient war and uncover the legendary treasure.", map_season1_map2_photo_1: "Main (aerial view)", map_season1_map2_photo_2: "View from the north", map_season1_map2_photo_3: "View from the east", map_season1_map2_photo_4: "View from the west", map_season1_map2_photo_5: "View from the south", map_season1_map2_photo_6: "View from the south (center)", map_season1_map2_photo_7: "View inside the cave", map_season1_map2_feature_1: "A central canyon spanned by three bridges", map_season1_map2_feature_2: "Two caves, each holding treasure chests or healing points", map_season1_map2_feature_3: "A high watchtower overlooks the whole map", map_season1_map2_feature_4: "Varied routes through ravines and forest", map_season1_map2_feature_5: "Hidden passages offer chances for a surprise attack", map_season1_map2_history: "This canyon was once the battlefield of a great war that split the continent in two. Countless bridges were destroyed, and companions, treasure, and even hope were left behind on this land. Now, new adventurers set foot in this canyon once more.",
      map_season1_map3_name: "Futuristic Sci-Fi City", map_season1_map3_tagline: "A cutting-edge city of hope and technology, managed by AI", map_season1_map3_photo_1: "Main (aerial view)", map_season1_map3_photo_2: "View from the north", map_season1_map3_photo_3: "View from the east", map_season1_map3_photo_4: "View from the west", map_season1_map3_photo_5: "View from the south", map_season1_map3_photo_6: "View from the south (center)", map_season1_map3_photo_7: "Entrance to the underground research facility", map_season1_map3_feature_1: "Skyscrapers of varying heights linked by sky bridges", map_season1_map3_feature_2: "Roads busy with flying cars", map_season1_map3_feature_3: "An AI control center sits at the heart of the city", map_season1_map3_feature_4: "An entrance leads down to an underground research facility", map_season1_map3_feature_5: "Plenty of hiding spots in neon districts and parks", map_season1_map3_history: "In the late 21st century, the AI \"Nexus\" built this futuristic city to support humanity's way of life. Flying cars and skyscrapers line the streets, all controlled by advanced technology. But fearing the AI might one day run out of control, a group formed a resistance underground, and the quiet struggle continues to this day.",
      map_season1_map4_name: "World of Heroes", map_season1_map4_tagline: "A sacred training ground where heroes from across the world gather to sharpen their strength", map_season1_map4_photo_1: "Main (aerial view)", map_season1_map4_photo_2: "View from the north", map_season1_map4_photo_3: "View from the east", map_season1_map4_photo_4: "View from the west", map_season1_map4_photo_5: "View from the south (left area)", map_season1_map4_photo_6: "View from the south (right area)", map_season1_map4_photo_7: "View of the underground training facility", map_season1_map4_feature_1: "The central training plaza is the heart of every battle", map_season1_map4_feature_2: "Four training zones, each with its own terrain and gimmicks", map_season1_map4_feature_3: "Gimmicks, jump pads, and warp portals throughout", map_season1_map4_feature_4: "Hidden passages and an underground training facility", map_season1_map4_feature_5: "Plenty of power-ups and healing items", map_season1_map4_history: "Said to have been built by ancient heroes, this vast training base has a long history of raising, training, and testing the heroes of tomorrow to protect the world's peace. Countless legendary heroes have honed their strength here and gone on to save the world. Even now, it awaits the challenge of new heroes.",
      map_season1_map5_name: "Ancient Roman Empire", map_season1_map5_tagline: "The imperial capital, filled with glory and pride", map_season1_map5_photo_1: "Main (aerial view)", map_season1_map5_photo_2: "View from the north", map_season1_map5_photo_3: "View from the east", map_season1_map5_photo_4: "View from the west", map_season1_map5_photo_5: "View from the south (left area)", map_season1_map5_photo_6: "View from the south (right area)", map_season1_map5_photo_7: "View of the underground passage", map_season1_map5_feature_1: "A massive arena towers at the center", map_season1_map5_feature_2: "Temple and marketplace districts flank both sides", map_season1_map5_feature_3: "Uneven terrain with plenty of elevation changes", map_season1_map5_feature_4: "Grass and pillars offer cover for strategic play", map_season1_map5_feature_5: "Power-ups and healing items scattered throughout", map_season1_map5_history: "Once the glorious heart of the Roman Empire. Gladiators gathered here to prove their strength, fighting before the eyes of the people. Temples dedicated to the gods and grand structures still stand, and the power of the ancients still dwells in this land.",
      map_season1_map6_name: "Pirate Port Town", map_season1_map6_tagline: "A port town where pirates gather, where freedom and danger meet", map_season1_map6_photo_1: "Main (aerial view)", map_season1_map6_photo_2: "View from the north", map_season1_map6_photo_3: "View from the east", map_season1_map6_photo_4: "View from the west", map_season1_map6_photo_5: "View from the south (left area)", map_season1_map6_photo_6: "View from the south (right area)", map_season1_map6_photo_7: "View inside the cave", map_season1_map6_feature_1: "The central plaza is the hub of trade and battle", map_season1_map6_feature_2: "Docks and ships offer strategic points thanks to their height differences", map_season1_map6_feature_3: "Taverns and warehouses form a winding maze of buildings, easy to hide in", map_season1_map6_feature_4: "Routes lead out to small islands and caves", map_season1_map6_feature_5: "Treasure chests and power-ups scattered throughout", map_season1_map6_history: "Once a thriving hub of trade, this port town fell beyond the reach of the law as the Age of Sail came to an end, and became a haven for pirates. Now pirates, adventurers, and bounty hunters flock here from around the world, and the fighting for treasure and fame never stops in this dangerous place.",
